"""Triage customer support tickets with SubQ Snap (subq-snap-preview).

For each ticket, one request to POST https://api.subq.ai/v1/systemone asks three
independent questions and gets typed answers with probabilities:
  urgent   (noul)   probability that the ticket needs a response within the hour
  team     (choice) billing / engineering / sales / other
  severity (score)  3 ordered levels: low / medium / high

Tickets the model is unsure about, or that fail with a per-ticket error, are
flagged `needs_human` with the reasons. The thresholds below are placeholders:
calibrate them on tickets you have already labelled before relying on them.

Input:  JSONL with {"id": ..., "text": ...} per line, or plain text with one ticket per line.
Output: JSONL, one result per ticket, with the raw answers kept for re-thresholding.

Usage:
    export SUBQ_API_KEY=...   # never put the key in this file
    python3 triage.py tickets.jsonl > triaged.jsonl
"""

from __future__ import annotations

import argparse
import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Placeholder thresholds; tune per question on labelled tickets.
URGENT_YES = 0.70           # noul >= this -> urgent
URGENT_NO = 0.30            # noul <= this -> not urgent; in between -> unsure
TEAM_MIN_CONFIDENCE = 0.60
SEVERITY_MIN_CONFIDENCE = 0.50

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Based on the support ticket text, does this ticket need a response within the hour?",
        "criteria": {
            "true": "Outage, data loss, security incident, blocked payment, or the customer cannot do business right now",
            "false": "Questions, feature requests, minor bugs, or anything that can wait until the next business day",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Based on the support ticket text, which team should own this ticket?",
        "criteria": {
            "billing": "Charges, invoices, refunds, payment methods, failed payments, tax or receipts",
            "engineering": "Bugs, crashes, errors, outages, performance, integrations, API or data problems",
            "sales": "Pricing questions, plan changes, upgrades, quotes, new purchases, contract terms",
            "other": None,
        },
    },
    "severity": {
        "type": "score",
        "instructions": "Based on the support ticket text, how severely is the customer affected?",
        "criteria": [
            "A question, request or cosmetic issue; the customer can work normally",
            "Something is broken or wrong, but a workaround exists or only part of the product is affected",
            "The customer cannot use the product or a critical function, or is losing money or data",
        ],
    },
}


class SnapError(Exception):
    def __init__(self, status: int | None, error_type: str, message: str) -> None:
        super().__init__(f"{status} {error_type}: {message}")
        self.status = status
        self.error_type = error_type


class FatalSnapError(SnapError):
    """Key, credit or access problem: every further request would fail the same way."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # urllib would resend the Authorization header to the redirect target.
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        return None


_OPENER = urllib.request.build_opener(_NoRedirect)


def decide(state, questions: dict, key: str, *, attempts: int = 5, timeout_s: float = 60.0,
           base_delay_s: float = 1.0, max_delay_s: float = 30.0) -> dict:
    data = json.dumps({"model": MODEL, "state": state, "questions": questions}).encode()
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    for attempt in range(attempts):
        last = attempt == attempts - 1
        try:
            req = urllib.request.Request(URL, data=data, headers=headers, method="POST")
            with _OPENER.open(req, timeout=timeout_s) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            detail = _detail(e)
            err_type, msg = detail.get("error_type", "http_error"), detail.get("message", "")
            if e.code in (401, 402, 403):
                raise FatalSnapError(e.code, err_type, msg) from e
            if not (e.code == 429 or e.code >= 500) or last:
                raise SnapError(e.code, err_type, msg) from e  # 400/422/3xx: retrying won't help
            retry_after = e.headers.get("Retry-After") if e.headers else None
        except (OSError, http.client.HTTPException, ValueError) as e:
            # Timeout, reset, truncated/invalid body: outcome unknown; decisions have no side effects, so retry.
            if last:
                raise SnapError(None, "network", f"{type(e).__name__}: {e}") from e
            retry_after = None
        delay = random.uniform(0, min(max_delay_s, base_delay_s * 2 ** attempt))
        if retry_after and retry_after.isdigit():
            delay = max(delay, min(float(retry_after), max_delay_s))
        time.sleep(delay)
    raise SnapError(None, "internal", "retry loop ended without a result")


def _detail(e: urllib.error.HTTPError) -> dict:
    try:
        payload = json.load(e)
    except (ValueError, OSError):
        return {}
    detail = payload.get("detail") if isinstance(payload, dict) else None
    return detail if isinstance(detail, dict) else {"message": str(payload)[:200]}


def interpret(answers: dict) -> dict:
    """Turn raw probabilities into a triage decision plus reasons for human review."""
    reasons = []

    p_urgent = answers["urgent"]["noul"]
    if p_urgent >= URGENT_YES:
        urgent = True
    elif p_urgent <= URGENT_NO:
        urgent = False
    else:
        urgent = None
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")

    team = answers["team"]["choice"]
    if answers["team"]["confidence"] < TEAM_MIN_CONFIDENCE:
        reasons.append(f"team unclear ({team}, confidence={answers['team']['confidence']:.2f})")
    if team == "other":
        reasons.append("no matching team")

    score = answers["severity"]["score"]  # 0..2, may fall between levels
    level = max(0, min(len(SEVERITY_LEVELS) - 1, round(score)))
    severity = SEVERITY_LEVELS[level]
    if answers["severity"]["confidence"] < SEVERITY_MIN_CONFIDENCE:
        reasons.append(f"severity unclear (score={score:.2f}, confidence={answers['severity']['confidence']:.2f})")

    # Inconsistent signals are worth a second look: urgent but low severity, or high severity but not urgent.
    if (urgent is True and level == 0) or (urgent is False and level == 2):
        reasons.append("urgency and severity disagree")

    return {"urgent": urgent, "team": team, "severity": severity,
            "needs_human": bool(reasons), "review_reasons": reasons}


def read_tickets(path: str):
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except ValueError:
                obj = None
            if isinstance(obj, dict) and "text" in obj:
                yield str(obj.get("id", n)), obj["text"]
            else:
                yield str(n), line


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="JSONL ({id, text}) or plain text, one ticket per line")
    args = parser.parse_args()

    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    total_tokens = flagged = failed = 0
    for ticket_id, text in read_tickets(args.tickets):
        result = {"id": ticket_id}
        try:
            resp = decide({"ticket_text": text}, QUESTIONS, key)
            result.update(interpret(resp["answers"]))
            result["raw_answers"] = resp["answers"]
            total_tokens += resp.get("usage", {}).get("input_tokens", 0)
        except FatalSnapError as e:
            print(f"aborting: {e}", file=sys.stderr)
            return 1
        except (SnapError, KeyError, TypeError) as e:
            failed += 1
            result.update({"urgent": None, "team": None, "severity": None,
                           "needs_human": True, "review_reasons": [f"triage failed: {e}"]})
        flagged += result["needs_human"]
        print(json.dumps(result), flush=True)

    print(f"done: {flagged} flagged for human review ({failed} failed), "
          f"{total_tokens} input tokens (~${total_tokens * 0.05 / 1e6:.4f})", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Triage customer support tickets with SubQ Snap (subq-snap-preview), standard library only.

For each ticket, one request to POST https://api.subq.ai/v1/systemone asks three independent questions:
  urgent    noul   -> probability the ticket is urgent
  team      choice -> billing / engineering / sales / other
  severity  score  -> 3 ordered levels (low / medium / high)
Code combines the answers and flags uncertain tickets for a human.

Usage:
    export SUBQ_API_KEY=...          # or run through a secrets-manager wrapper; never hard-code it
    python3 triage.py tickets.jsonl > triaged.jsonl

Input: JSONL, one object per line with "id" and "text" (a plain-text file is also accepted:
one ticket per non-empty line, ids are line numbers). Output: JSONL, one result per ticket,
including the raw probabilities so thresholds can be retuned without calling the API again.

The thresholds below are placeholders. Tune them on tickets you have already labelled.
"""

from __future__ import annotations

import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Placeholder thresholds: calibrate per question on labelled tickets.
URGENT_YES = 0.70          # noul >= this -> urgent
URGENT_NO = 0.30           # noul <= this -> not urgent; in between -> human review
MIN_TEAM_CONFIDENCE = 0.60
MIN_SEVERITY_CONFIDENCE = 0.50

MAX_STATE_CHARS = 20_000   # tickets are short; this keeps a pasted log dump from blowing up the request
ATTEMPTS = 5
TIMEOUT_S = 60.0

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Based on the ticket text, does this ticket need a response within the hour?",
        "criteria": {
            "true": "Outage, data loss, security incident, blocked payment, or the customer cannot work at all right now",
            "false": "Questions, feature requests, minor bugs, or anything that can wait until the next business day",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Based on the ticket text, which team should own this ticket?",
        "criteria": {
            "billing": "Charges, invoices, refunds, payment methods, failed payments, receipts",
            "engineering": "Bugs, crashes, errors, outages, performance problems, integrations or API not working",
            "sales": "Pricing questions, plans, upgrades, quotes, new purchases, contract or seat changes",
            "other": "Anything that does not fit billing, engineering or sales",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "Based on the ticket text, how badly is the customer affected?",
        "criteria": [
            "Low: a question, cosmetic issue or request; nothing is broken for the customer",
            "Medium: something is broken or wrong, but the customer has a workaround or only part of the product is affected",
            "High: the customer cannot use the product, is losing money or data, or has a security problem",
        ],
    },
}


class SnapError(Exception):
    """No decision was produced. `status` is the HTTP status, or None for a local/network failure."""

    def __init__(self, status: int | None, error_type: str, message: str) -> None:
        super().__init__(f"{status} {error_type}: {message}")
        self.status = status
        self.error_type = error_type


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001 - urllib signature
        return None  # never resend the Authorization header to another host


_OPENER = urllib.request.build_opener(_NoRedirect)


def _detail(e: urllib.error.HTTPError) -> dict:
    try:
        payload = json.load(e)
    except ValueError:
        return {}
    detail = payload.get("detail") if isinstance(payload, dict) else None
    return detail if isinstance(detail, dict) else {"message": str(payload)[:200]}


def decide(key: str, state: str | dict, questions: dict) -> dict:
    """One Decisions request with bounded retries on 429, 5xx, timeouts and dropped connections.

    Retrying is safe: a decision request has no side effects.
    """
    data = json.dumps({"model": MODEL, "state": state, "questions": questions}).encode()
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    for attempt in range(ATTEMPTS):
        last = attempt == ATTEMPTS - 1
        try:
            req = urllib.request.Request(URL, data=data, headers=headers)
            with _OPENER.open(req, timeout=TIMEOUT_S) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            detail = _detail(e)
            if not (e.code == 429 or e.code >= 500) or last:
                raise SnapError(e.code, detail.get("error_type", "http_error"), detail.get("message", "")) from e
        except (OSError, http.client.HTTPException, ValueError) as e:
            # timeouts, resets, truncated or non-JSON bodies: outcome unknown, retry
            if last:
                raise SnapError(None, "network", f"{type(e).__name__}: {e}") from e
        time.sleep(random.uniform(0, min(30.0, 1.0 * 2**attempt)))  # exponential backoff, full jitter
    raise SnapError(None, "internal", "retry loop ended without a result")


def _severity_level(answer: dict) -> str:
    """Most likely severity level. `probabilities` may be a list (in level order) or a mapping."""
    probs = answer.get("probabilities")
    if isinstance(probs, list) and len(probs) == len(SEVERITY_LEVELS):
        return SEVERITY_LEVELS[max(range(len(probs)), key=probs.__getitem__)]
    if isinstance(probs, dict) and probs:
        best = max(probs, key=probs.get)
        for i, desc in enumerate(QUESTIONS["severity"]["criteria"]):
            if best in (desc, str(i), SEVERITY_LEVELS[i]):
                return SEVERITY_LEVELS[i]
    # Fall back to the probability-weighted score, rounded to the nearest level.
    # Assumes 0-based levels; verify against a real response before relying on it.
    idx = round(float(answer["score"]))
    return SEVERITY_LEVELS[min(max(idx, 0), len(SEVERITY_LEVELS) - 1)]


def triage(ticket_id: str, text: str, key: str) -> dict:
    result: dict = {"id": ticket_id}
    state = {"ticket_text": text[:MAX_STATE_CHARS]}
    try:
        resp = decide(key, state, QUESTIONS)
    except SnapError as e:
        if e.status in (401, 402, 403):
            raise  # key, credits or model access: every later ticket would fail too
        # 400/422 (e.g. rejected input) or retries exhausted: a human handles this one
        return {**result, "needs_human": True, "reasons": [f"api_error: {e}"]}

    a = resp["answers"]
    p_urgent = float(a["urgent"]["noul"])
    team, team_conf = a["team"]["choice"], float(a["team"]["confidence"])
    sev_conf = float(a["severity"]["confidence"])

    reasons = []
    if URGENT_NO < p_urgent < URGENT_YES:
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")
    if team_conf < MIN_TEAM_CONFIDENCE:
        reasons.append(f"team unclear ({team}, confidence={team_conf:.2f})")
    if team == "other":
        reasons.append("no matching team")
    if sev_conf < MIN_SEVERITY_CONFIDENCE:
        reasons.append(f"severity unclear (confidence={sev_conf:.2f})")

    return {
        **result,
        "urgent": p_urgent >= URGENT_YES,
        "team": team,
        "severity": _severity_level(a["severity"]),
        "needs_human": bool(reasons),
        "reasons": reasons,
        "raw": {
            "urgent_p": p_urgent,
            "team_probabilities": a["team"].get("probabilities"),
            "team_confidence": team_conf,
            "severity_score": a["severity"].get("score"),
            "severity_probabilities": a["severity"].get("probabilities"),
            "severity_confidence": sev_conf,
        },
        "input_tokens": resp.get("usage", {}).get("input_tokens"),
    }


def load_tickets(path: str) -> list[tuple[str, str]]:
    tickets = []
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except ValueError:
                obj = None
            if isinstance(obj, dict) and "text" in obj:
                tickets.append((str(obj.get("id", n)), str(obj["text"])))
            else:
                tickets.append((str(n), line))
    return tickets


def main() -> int:
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} TICKETS_FILE", file=sys.stderr)
        return 2
    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    tickets = load_tickets(sys.argv[1])
    flagged = tokens = 0
    for ticket_id, text in tickets:
        try:
            r = triage(ticket_id, text, key)
        except SnapError as e:
            print(f"aborting at ticket {ticket_id}: {e}", file=sys.stderr)
            return 1
        print(json.dumps(r), flush=True)
        flagged += r["needs_human"]
        tokens += r.get("input_tokens") or 0
    print(f"{len(tickets)} tickets, {flagged} flagged for human review, {tokens} input tokens "
          f"(~${tokens * 0.05 / 1e6:.4f})", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Triage customer support tickets with SubQ Snap (subq-snap-preview).

For each ticket, one request to POST https://api.subq.ai/v1/systemone asks three
independent questions: urgent (noul), team (choice), severity (score, 3 levels).
Uncertain or failed tickets are flagged with needs_human=true and a reason.

Input:  JSONL, one ticket per line: {"id": "...", "text": "..."}
Output: JSONL, one result per ticket (raw probabilities kept for later recalibration).

Usage:
    export SUBQ_API_KEY=...   # never put the key in a file or argument
    python3 triage.py tickets.jsonl > triaged.jsonl

Standard library only.
"""

from __future__ import annotations

import argparse
import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Placeholder thresholds. Calibrate them on tickets you have already labelled.
URGENT_YES = 0.7          # noul >= this -> urgent
URGENT_NO = 0.3           # noul <= this -> not urgent; in between -> human
TEAM_MIN_CONFIDENCE = 0.6
SEVERITY_MIN_CONFIDENCE = 0.5

MAX_TICKET_CHARS = 20_000  # trim very long tickets; triage rarely needs more

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Read the support ticket in state.ticket. Does it need a response within the hour?",
        "criteria": {
            "true": "Outage, data loss, security incident, or the customer is blocked from paying or being paid",
            "false": "Questions, feature requests, minor bugs, or anything that can wait until the next business day",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Read the support ticket in state.ticket. Which team should own it?",
        "criteria": {
            "billing": "Charges, invoices, refunds, payment methods, failed payments, tax",
            "engineering": "Bugs, crashes, errors, outages, performance, integrations, API problems",
            "sales": "Pricing questions, plans, upgrades, quotes, new purchases, contract terms",
            "other": None,
        },
    },
    "severity": {
        "type": "score",
        "instructions": "Read the support ticket in state.ticket. How badly is the customer affected?",
        "criteria": [
            "Question, request or cosmetic issue; the customer is not blocked",
            "Something is broken or wrong but the customer can still work, e.g. with a workaround",
            "The customer cannot use the product or a critical part of it, or money or data is at risk",
        ],
    },
}


class SnapError(Exception):
    def __init__(self, status: int | None, error_type: str, message: str) -> None:
        super().__init__(f"{status} {error_type}: {message}")
        self.status = status
        self.error_type = error_type


class FatalError(SnapError):
    """Key, credits or model access problem: every further request would fail too."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # Following a redirect could resend the Authorization header to another host.
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        return None


_OPENER = urllib.request.build_opener(_NoRedirect)


def _detail(e: urllib.error.HTTPError) -> dict:
    try:
        payload = json.load(e)
    except (ValueError, OSError):
        return {}
    detail = payload.get("detail") if isinstance(payload, dict) else None
    return detail if isinstance(detail, dict) else {"message": str(payload)[:200]}


def decide(key: str, state: dict, *, attempts: int = 5, timeout_s: float = 60.0) -> dict:
    """One Decisions request with bounded retries on 429, 5xx and network errors."""
    body = json.dumps({"model": MODEL, "state": state, "questions": QUESTIONS}).encode()
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}

    for attempt in range(attempts):
        last = attempt == attempts - 1
        delay = random.uniform(0, min(30.0, 2.0**attempt))  # exponential backoff, full jitter
        try:
            req = urllib.request.Request(URL, data=body, headers=headers, method="POST")
            with _OPENER.open(req, timeout=timeout_s) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            d = _detail(e)
            err = (e.code, d.get("error_type", "http_error"), d.get("message", ""))
            if e.code in (401, 402, 403):
                raise FatalError(*err) from e
            if not (e.code == 429 or e.code >= 500) or last:
                raise SnapError(*err) from e  # 400 / 422 / 3xx: retrying will not help
            retry_after = e.headers.get("Retry-After") if e.headers else None
            if retry_after and retry_after.isdigit():
                delay = min(60.0, float(retry_after))
        except (OSError, http.client.HTTPException, ValueError) as e:
            # Timeout, reset, truncated/invalid body. Decisions have no side effects, so retry.
            if last:
                raise SnapError(None, "network", f"{type(e).__name__}: {e}") from e
        print(f"  retrying in {delay:.1f}s (attempt {attempt + 2}/{attempts})", file=sys.stderr)
        time.sleep(delay)
    raise SnapError(None, "internal", "retry loop ended without a result")


def interpret(answers: dict) -> dict:
    """Turn raw answers into a triage decision; flag anything uncertain for a human."""
    reasons = []

    p_urgent = answers["urgent"]["noul"]
    if p_urgent >= URGENT_YES:
        urgent = True
    elif p_urgent <= URGENT_NO:
        urgent = False
    else:
        urgent = None
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")

    team_a = answers["team"]
    team = team_a["choice"]
    if team_a["confidence"] < TEAM_MIN_CONFIDENCE:
        reasons.append(f"team unclear ({team}, confidence={team_a['confidence']:.2f})")
    if team == "other":
        reasons.append("no matching team")

    sev_a = answers["severity"]
    level = max(0, min(len(SEVERITY_LEVELS) - 1, round(sev_a["score"])))  # levels are 0-based
    severity = SEVERITY_LEVELS[level]
    if sev_a["confidence"] < SEVERITY_MIN_CONFIDENCE:
        reasons.append(f"severity unclear (score={sev_a['score']:.2f}, confidence={sev_a['confidence']:.2f})")

    return {
        "urgent": urgent,
        "team": team,
        "severity": severity,
        "needs_human": bool(reasons),
        "human_reasons": reasons,
        "raw": {
            "urgent_p": p_urgent,
            "team_probabilities": team_a.get("probabilities"),
            "team_confidence": team_a["confidence"],
            "severity_score": sev_a["score"],
            "severity_probabilities": sev_a.get("probabilities"),
            "severity_confidence": sev_a["confidence"],
        },
    }


def triage(key: str, ticket_id: str, text: str) -> dict:
    out: dict = {"id": ticket_id}
    if not text.strip():
        return out | {"needs_human": True, "human_reasons": ["empty ticket"]}
    try:
        result = decide(key, {"ticket": text[:MAX_TICKET_CHARS]})
        out |= interpret(result["answers"])
        out["input_tokens"] = result.get("usage", {}).get("input_tokens")
    except FatalError:
        raise
    except SnapError as e:
        out |= {"needs_human": True, "human_reasons": [f"API error: {e}"]}
    except (KeyError, TypeError) as e:
        out |= {"needs_human": True, "human_reasons": [f"unexpected response shape: {e!r}"]}
    return out


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="JSONL file with {'id', 'text'} per line ('-' for stdin)")
    args = parser.parse_args()

    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    src = sys.stdin if args.tickets == "-" else open(args.tickets, encoding="utf-8")
    flagged = total = 0
    with src:
        for n, line in enumerate(src, 1):
            if not line.strip():
                continue
            try:
                ticket = json.loads(line)
                ticket_id, text = str(ticket.get("id", n)), str(ticket["text"])
            except (ValueError, KeyError, AttributeError) as e:
                print(f"line {n}: skipped, bad input ({e!r})", file=sys.stderr)
                continue
            try:
                res = triage(key, ticket_id, text)
            except FatalError as e:
                print(f"stopping: {e} (check key, credits or model access)", file=sys.stderr)
                return 1
            print(json.dumps(res), flush=True)
            total += 1
            flagged += res["needs_human"]

    print(f"done: {total} tickets, {flagged} flagged for a human", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Triage customer support tickets with SubQ Snap (Decisions API).

For each ticket, one API call asks three questions:
  - urgent   (noul):   probability the ticket is urgent
  - team     (choice): billing | engineering | sales | other
  - severity (score):  low < medium < high

Low-confidence answers are flagged for human review.

Input:  JSONL file (or stdin) with one ticket per line: {"id": "...", "text": "..."}
        Plain-text lines are also accepted; the line number becomes the id.
Output: JSONL to stdout, one result per ticket.

Usage:
    export SUBQ_API_KEY=sk-...
    python triage.py tickets.jsonl > triaged.jsonl
"""

import argparse
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Thresholds below which a decision is handed to a human.
URGENT_UNSURE_BAND = (0.3, 0.7)  # noul probability inside this band is ambiguous
MIN_TEAM_CONFIDENCE = 0.6
MIN_SEVERITY_CONFIDENCE = 0.5

MAX_RETRIES = 5
BASE_BACKOFF_S = 1.0
MAX_BACKOFF_S = 30.0
TIMEOUT_S = 30
RETRYABLE_STATUSES = {429, 500, 502, 503, 504}
# Errors that will fail every request the same way; stop instead of burning the queue.
FATAL_STATUSES = {401, 402, 403}

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Is this support ticket urgent, i.e. does it need a response within hours?",
        "criteria": {
            "true": "Outage, data loss, security issue, blocked production use, or a customer threatening to churn",
            "false": "Routine question, feature request, or issue with a workaround",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this support ticket?",
        "criteria": {
            "billing": "Payments, invoices, refunds, charges, subscription or plan changes",
            "engineering": "Bugs, errors, outages, performance, integrations, API or technical problems",
            "sales": "Pricing inquiries, upgrades, new purchases, quotes, demos, contract negotiation",
            "other": "Anything that does not clearly fit billing, engineering, or sales",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the customer's problem?",
        "criteria": [
            "Low: minor inconvenience, question, or cosmetic issue",
            "Medium: a feature is degraded or a workaround is needed",
            "High: service unusable, data loss, security, or financial impact",
        ],
    },
}


class FatalAPIError(Exception):
    pass


class APIError(Exception):
    def __init__(self, status, message):
        super().__init__(f"HTTP {status}: {message}")
        self.status = status


def _error_message(body):
    try:
        detail = json.loads(body).get("detail")
        if isinstance(detail, dict):
            return f"{detail.get('error_type')}: {detail.get('message')}"
        return str(detail)
    except (ValueError, AttributeError):
        return body[:500]


def _backoff(attempt, retry_after=None):
    if retry_after:
        try:
            return min(float(retry_after), MAX_BACKOFF_S)
        except ValueError:
            pass
    delay = min(BASE_BACKOFF_S * 2**attempt, MAX_BACKOFF_S)
    return random.uniform(0, delay)  # full jitter


def call_snap(api_key, ticket_text):
    payload = json.dumps(
        {"model": MODEL, "state": ticket_text, "questions": QUESTIONS}
    ).encode()
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    for attempt in range(MAX_RETRIES + 1):
        req = urllib.request.Request(API_URL, data=payload, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT_S) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            msg = _error_message(body)
            if e.code in FATAL_STATUSES:
                raise FatalAPIError(f"HTTP {e.code}: {msg}") from e
            if e.code not in RETRYABLE_STATUSES or attempt == MAX_RETRIES:
                raise APIError(e.code, msg) from e
            wait = _backoff(attempt, e.headers.get("Retry-After"))
            print(f"  HTTP {e.code}, retrying in {wait:.1f}s ({msg})", file=sys.stderr)
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            if attempt == MAX_RETRIES:
                raise APIError(None, f"network error: {e}") from e
            wait = _backoff(attempt)
            print(f"  network error, retrying in {wait:.1f}s ({e})", file=sys.stderr)
        time.sleep(wait)


def _severity_label(answer):
    """Map the probability-weighted score to the nearest level via the legend."""
    score = answer["score"]
    legend = answer.get("legend") or {}
    if legend:
        nearest = min(legend, key=lambda k: abs(float(k) - score))
        index = sorted(legend, key=float).index(nearest)
    else:
        index = max(0, min(len(SEVERITY_LEVELS) - 1, round(score)))
    return SEVERITY_LEVELS[index]


def interpret(answers):
    reasons = []

    p_urgent = answers["urgent"]["noul"]
    lo, hi = URGENT_UNSURE_BAND
    if lo < p_urgent < hi:
        reasons.append(f"urgency ambiguous (p={p_urgent:.2f})")

    team = answers["team"]
    team_conf = team.get("confidence")
    if team_conf is not None and team_conf < MIN_TEAM_CONFIDENCE:
        reasons.append(f"team uncertain (confidence={team_conf:.2f})")

    sev = answers["severity"]
    sev_conf = sev.get("confidence")
    if sev_conf is not None and sev_conf < MIN_SEVERITY_CONFIDENCE:
        reasons.append(f"severity uncertain (confidence={sev_conf:.2f})")

    return {
        "urgent": p_urgent >= 0.5,
        "urgent_probability": p_urgent,
        "team": team["choice"],
        "team_confidence": team_conf,
        "team_probabilities": team.get("probabilities"),
        "severity": _severity_label(sev),
        "severity_score": sev["score"],
        "severity_confidence": sev_conf,
        "needs_human": bool(reasons),
        "review_reasons": reasons,
    }


def read_tickets(stream):
    for lineno, line in enumerate(stream, 1):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            obj = line
        if isinstance(obj, dict):
            yield str(obj.get("id", lineno)), str(obj.get("text", ""))
        else:
            yield str(lineno), str(obj)


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("input", nargs="?", help="JSONL/text file of tickets (default: stdin)")
    args = parser.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        sys.exit("SUBQ_API_KEY is not set")

    stream = open(args.input, encoding="utf-8") if args.input else sys.stdin
    counts = {"ok": 0, "needs_human": 0, "failed": 0}

    with stream:
        for ticket_id, text in read_tickets(stream):
            result = {"id": ticket_id}
            if not text.strip():
                result.update(needs_human=True, review_reasons=["empty ticket"])
            else:
                try:
                    response = call_snap(api_key, text)
                    result.update(interpret(response["answers"]))
                except FatalAPIError as e:
                    sys.exit(f"Aborting at ticket {ticket_id}: {e}")
                except (APIError, KeyError, TypeError, ValueError) as e:
                    # Per-ticket failure (e.g. too long, malformed response): route to a human.
                    counts["failed"] += 1
                    result.update(needs_human=True, error=str(e), review_reasons=["triage failed"])

            if result["needs_human"]:
                counts["needs_human"] += 1
            else:
                counts["ok"] += 1
            print(json.dumps(result), flush=True)

    print(
        f"done: {counts['ok']} auto-triaged, {counts['needs_human']} flagged for human "
        f"({counts['failed']} due to errors)",
        file=sys.stderr,
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Triage customer support tickets with SubQ Snap (Decisions API).

For each ticket, one request asks three questions:
  urgent   (noul)   - is the ticket urgent?
  team     (choice) - billing / engineering / sales / other
  severity (score)  - low / medium / high

Input:  JSONL file with {"id": ..., "text": ...} per line, or a plain text
        file with one ticket per line (id = line number).
Output: JSONL on stdout, one result per ticket. Tickets the model is unsure
        about, or that failed, get "needs_human": true plus reasons.

Usage:  SUBQ_API_KEY=... python3 triage.py tickets.jsonl > triaged.jsonl
"""

import argparse
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

TEAMS = {
    "billing": "Invoices, charges, refunds, payment methods, pricing disputes, subscription changes.",
    "engineering": "Bugs, outages, errors, performance problems, integrations, API or technical issues.",
    "sales": "New purchases, upgrades, quotes, demos, contract or plan inquiries from prospects.",
    "other": "Anything that does not clearly fit billing, engineering or sales.",
}
SEVERITY_LEVELS = [
    "low: minor inconvenience, question or cosmetic issue; workaround exists",
    "medium: noticeable impact on the customer's work, but limited in scope or with a workaround",
    "high: service down, data loss, security issue, money wrongly taken, or many users blocked",
]
SEVERITY_NAMES = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Does this support ticket need an urgent response (within hours, not days)?",
        "criteria": {
            "true": "Customer is blocked, losing money or data, facing a security issue, or a deadline is imminent.",
            "false": "The issue can wait for normal queue handling without significant harm.",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this support ticket?",
        "criteria": TEAMS,
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the customer's problem described in this ticket?",
        "criteria": SEVERITY_LEVELS,
    },
}

# Uncertainty thresholds: anything inside these bands is flagged for a human.
URGENT_UNSURE_BAND = (0.3, 0.7)  # P(urgent) in this range -> unsure
MIN_TEAM_CONFIDENCE = 0.6
MIN_SEVERITY_CONFIDENCE = 0.5
MAX_SEVERITY_DISTANCE = 0.35  # weighted score too far from nearest level -> unsure

RETRYABLE_STATUS = {429, 500, 502, 503, 504}
FATAL_STATUS = {401, 402, 403}  # bad key / no credits / no model access: stop the run


class FatalAPIError(Exception):
    pass


class TicketError(Exception):
    pass


def call_snap(api_key, ticket_text, max_retries, timeout):
    body = json.dumps({"model": MODEL, "state": ticket_text, "questions": QUESTIONS}).encode()
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    for attempt in range(max_retries + 1):
        req = urllib.request.Request(API_URL, data=body, headers=headers, method="POST")
        retry_after = None
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            detail = _error_detail(e)
            if e.code in FATAL_STATUS:
                raise FatalAPIError(f"HTTP {e.code}: {detail}") from e
            if e.code not in RETRYABLE_STATUS:
                # 400 (too long / rejected), 422 (invalid request): retrying won't help.
                raise TicketError(f"HTTP {e.code}: {detail}") from e
            last_error = f"HTTP {e.code}: {detail}"
            retry_after = _parse_retry_after(e.headers.get("Retry-After"))
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            last_error = f"network error: {e}"
        except json.JSONDecodeError as e:
            last_error = f"invalid JSON response: {e}"

        if attempt == max_retries:
            break
        delay = retry_after if retry_after is not None else min(60, 2**attempt) + random.uniform(0, 1)
        print(f"  retry {attempt + 1}/{max_retries} in {delay:.1f}s ({last_error})", file=sys.stderr)
        time.sleep(delay)

    raise TicketError(f"gave up after {max_retries + 1} attempts: {last_error}")


def _error_detail(e):
    try:
        detail = json.loads(e.read()).get("detail", {})
        if isinstance(detail, dict):
            return f"{detail.get('error_type', '?')}: {detail.get('message', '')}"
        return str(detail)
    except Exception:
        return e.reason


def _parse_retry_after(value):
    try:
        return max(0.0, float(value))
    except (TypeError, ValueError):
        return None


def interpret(answers):
    reasons = []

    p_urgent = answers["urgent"]["noul"]
    if URGENT_UNSURE_BAND[0] <= p_urgent <= URGENT_UNSURE_BAND[1]:
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")

    team = answers["team"]
    if team["confidence"] < MIN_TEAM_CONFIDENCE:
        reasons.append(f"team unclear (confidence={team['confidence']:.2f})")

    sev = answers["severity"]
    level = min(len(SEVERITY_NAMES) - 1, max(0, round(sev["score"])))
    if sev["confidence"] < MIN_SEVERITY_CONFIDENCE:
        reasons.append(f"severity unclear (confidence={sev['confidence']:.2f})")
    elif abs(sev["score"] - level) > MAX_SEVERITY_DISTANCE:
        reasons.append(f"severity between levels (score={sev['score']:.2f})")

    return {
        "urgent": p_urgent > 0.5,
        "urgent_probability": round(p_urgent, 3),
        "team": team["choice"],
        "team_confidence": round(team["confidence"], 3),
        "severity": SEVERITY_NAMES[level],
        "severity_score": round(sev["score"], 3),
        "severity_confidence": round(sev["confidence"], 3),
        "needs_human": bool(reasons),
        "reasons": reasons,
    }


def load_tickets(path):
    with open(path, encoding="utf-8") as f:
        lines = [line.strip() for line in f]
    tickets = []
    for n, line in enumerate(lines, 1):
        if not line:
            continue
        if path.endswith(".jsonl"):
            obj = json.loads(line)
            tickets.append((obj.get("id", n), obj["text"]))
        else:
            tickets.append((n, line))
    return tickets


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("tickets", help="tickets file (.jsonl with id/text, or one ticket per line)")
    ap.add_argument("--max-retries", type=int, default=5)
    ap.add_argument("--timeout", type=float, default=60.0)
    args = ap.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        sys.exit("SUBQ_API_KEY is not set")

    counts = {"ok": 0, "needs_human": 0, "failed": 0}
    for ticket_id, text in load_tickets(args.tickets):
        print(f"ticket {ticket_id}...", file=sys.stderr)
        try:
            resp = call_snap(api_key, text, args.max_retries, args.timeout)
            result = interpret(resp["answers"])
        except FatalAPIError as e:
            sys.exit(f"aborting: {e}")
        except (TicketError, KeyError, TypeError) as e:
            result = {"needs_human": True, "reasons": [f"triage failed: {e}"], "error": True}
            counts["failed"] += 1
        else:
            counts["needs_human" if result["needs_human"] else "ok"] += 1
        print(json.dumps({"id": ticket_id, **result}), flush=True)

    print(f"done: {counts}", file=sys.stderr)


if __name__ == "__main__":
    main()

