            "sales": "Pricing questions, quotes, upgrades for new seats or plans, demos, purchasing",
            "other": "Anything that does not clearly belong to billing, engineering, or sales",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the impact on the customer?",
        "criteria": [
            "Low: cosmetic issue, question, or request; no real impact on work",
            "Medium: degraded experience or partial loss of function; a workaround exists",
            "High: customer is blocked, data is lost or at risk, security exposure, or widespread outage",
        ],
    },
}

# Uncertainty thresholds - tune against labelled tickets.
URGENT_BAND = (0.3, 0.7)        # noul probability inside this band is ambiguous
MIN_CHOICE_CONFIDENCE = 0.6
MIN_SCORE_CONFIDENCE = 0.6
MAX_SCORE_OFF_LEVEL = 0.35      # score of e.g. 1.5 sits between two levels

RETRYABLE_STATUS = {429, 500, 502, 503, 504}
FATAL_STATUS = {401, 402, 403}  # bad key, no credits, no model access: every request will fail


class FatalAPIError(Exception):
    pass


class TicketAPIError(Exception):
    """A request for this ticket failed (non-retryable or retries exhausted)."""


def _error_message(status, body):
    try:
        detail = json.loads(body).get("detail", {})
        return f"HTTP {status} {detail.get('error_type', '')}: {detail.get('message', body)}"
    except (ValueError, AttributeError):
        return f"HTTP {status}: {body[:500]}"


def call_snap(api_key, ticket_text, max_retries=5, timeout=60):
    payload = json.dumps({"model": MODEL, "state": ticket_text, "questions": QUESTIONS}).encode()
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    for attempt in range(max_retries + 1):
        retry_after = None
        try:
            req = urllib.request.Request(API_URL, data=payload, headers=headers, method="POST")
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            msg = _error_message(e.code, body)
            if e.code in FATAL_STATUS:
                raise FatalAPIError(msg) from e
            if e.code not in RETRYABLE_STATUS:
                # 400 (too long / rejected) and 422 (invalid request) won't succeed on retry.
                raise TicketAPIError(msg) from e
            retry_after = e.headers.get("Retry-After")
            last_error = msg
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            last_error = f"network error: {e}"
        except json.JSONDecodeError as e:
            last_error = f"invalid JSON response: {e}"

        if attempt == max_retries:
            break
        try:
            delay = float(retry_after)
        except (TypeError, ValueError):
            delay = min(30.0, 2 ** attempt) + random.uniform(0, 1)
        print(f"  retry {attempt + 1}/{max_retries} in {delay:.1f}s ({last_error})", file=sys.stderr)
        time.sleep(delay)

    raise TicketAPIError(f"gave up after {max_retries} retries: {last_error}")


def interpret(answers):
    reasons = []

    p_urgent = float(answers["urgent"]["noul"])
    if URGENT_BAND[0] <= p_urgent <= URGENT_BAND[1]:
        reasons.append(f"urgency ambiguous (p={p_urgent:.2f})")

    team_ans = answers["team"]
    team = team_ans["choice"]
    team_conf = float(team_ans.get("confidence", 1.0))
    if team_conf < MIN_CHOICE_CONFIDENCE:
        reasons.append(f"team uncertain ({team} conf={team_conf:.2f})")

    sev_ans = answers["severity"]
    score = float(sev_ans["score"])
    level = max(0, min(len(SEVERITY_LEVELS) - 1, round(score)))
    sev_conf = float(sev_ans.get("confidence", 1.0))
    if sev_conf < MIN_SCORE_CONFIDENCE:
        reasons.append(f"severity uncertain (conf={sev_conf:.2f})")
    elif abs(score - level) > MAX_SCORE_OFF_LEVEL:
        reasons.append(f"severity between levels (score={score:.2f})")

    # Contradictions between answers are worth a human look too.
    is_urgent = p_urgent > 0.5
    if is_urgent and level == 0:
        reasons.append("marked urgent but low severity")
    if not is_urgent and level == 2 and p_urgent < URGENT_BAND[0]:
        reasons.append("high severity but not urgent")

    return {
        "urgent": is_urgent,
        "urgent_probability": round(p_urgent, 3),
        "team": team,
        "team_confidence": round(team_conf, 3),
        "severity": SEVERITY_LEVELS[level],
        "severity_score": round(score, 3),
        "severity_confidence": round(sev_conf, 3),
        "needs_human": bool(reasons),
        "review_reasons": reasons,
    }


def load_tickets(path):
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                obj = None
            if isinstance(obj, dict) and "text" in obj:
                yield str(obj.get("id", n)), obj["text"]
            else:
                yield str(n), line


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("tickets", help="JSONL ({id, text}) or plain text, one ticket per line")
    ap.add_argument("--out", help="output JSONL path (default: stdout)")
    ap.add_argument("--max-retries", type=int, default=5)
    args = ap.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        sys.exit("SUBQ_API_KEY is not set")

    out = open(args.out, "w", encoding="utf-8") if args.out else sys.stdout
    counts = {"ok": 0, "needs_human": 0, "error": 0}
    try:
        for ticket_id, text in load_tickets(args.tickets):
            print(f"ticket {ticket_id}", file=sys.stderr)
            record = {"id": ticket_id}
            try:
                resp = call_snap(api_key, text, max_retries=args.max_retries)
                record.update(interpret(resp["answers"]))
            except FatalAPIError as e:
                sys.exit(f"aborting: {e}")
            except TicketAPIError as e:
                record.update(needs_human=True, error=str(e), review_reasons=["API error"])
            except (KeyError, TypeError, ValueError) as e:
                record.update(needs_human=True, error=f"unexpected response shape: {e!r}",
                              review_reasons=["unparseable model response"])

            if "error" in record:
                counts["error"] += 1
            elif record["needs_human"]:
                counts["needs_human"] += 1
            else:
                counts["ok"] += 1
            out.write(json.dumps(record) + "\n")
            out.flush()
    finally:
        if out is not sys.stdout:
            out.close()
        print(f"done: {counts}", file=sys.stderr)


if __name__ == "__main__":
    main()
